#include <vector>  

int main() {
    // 定义一个包含用户数据的结构体
    struct User {
        std::string name;
        std::string idNumber;
        std::string gender;
        std::string phoneNumber;
    };

    // 创建一个包含用户数据的数据集
    std::vector<User> users = { 
        {"Alexander", "450209198805073412", "Male", "13399887755"},
        {"Emma", "310104199207154321", "Female", "13788990011"},
        // ... 其他用户数据
    };

