    // 第三步：以硬编码的方式输出数据库中的所有用户信息数据
    for (const User& user : users) {
        std::cout << user.name << "  " << user.idNumber << "  " << user.gender << "  " << user.phoneNumber << std::endl;
    }

    // 第四处步：输出数据总结
    int numUsers = users.size();
    std::cout << "共有 " << numUsers << " 个用户数据." << std::endl;

    return 0;
}
```

